:root {
  --bg: #1a1c2c;
  --card-bg: #2a2d45;
  --accent: #f4a261;
  --text: #e0e0e0;
  --highlight: #e76f51;
  --btn-bg: #3a3f5c;
  --btn-hover: #4a5070;
  --btn-active: #f4a261;
  --btn-active-text: #1a1c2c;
  --door-color: #6b7280;
  --door-open: #9ca3af;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  background: var(--bg);
  color: var(--text);
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
}

.elevator-card {
  background: var(--card-bg);
  border: 4px solid var(--accent);
  border-radius: 12px;
  padding: 24px;
  width: 100%;
  max-width: 400px;
  box-shadow: 0 8px 0 rgba(0,0,0,0.3);
}

h1 {
  font-size: 1.5rem;
  text-align: center;
  margin-bottom: 20px;
  color: var(--accent);
  text-transform: uppercase;
  letter-spacing: 2px;
}

.display {
  background: #0d0f1a;
  border: 3px solid var(--highlight);
  border-radius: 8px;
  padding: 16px;
  margin-bottom: 20px;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.floor-display,
.direction-display {
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.label {
  font-size: 0.9rem;
  text-transform: uppercase;
  letter-spacing: 1px;
  color: #9ca3af;
}

.value {
  font-size: 1.8rem;
  font-weight: bold;
  color: var(--accent);
  font-family: 'Courier New', monospace;
}

.doors {
  display: flex;
  height: 80px;
  margin-top: 8px;
  border: 2px solid #4a5070;
  border-radius: 4px;
  overflow: hidden;
  position: relative;
}

.door {
  flex: 1;
  background: var(--door-color);
  transition: transform 0.3s ease;
  position: relative;
}

.door.left {
  transform-origin: left;
}

.door.right {
  transform-origin: right;
}

.doors.open .door.left {
  transform: scaleX(0.3);
  background: var(--door-open);
}

.doors.open .door.right {
  transform: scaleX(0.3);
  background: var(--door-open);
}

.panel {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 12px;
  margin-bottom: 20px;
}

.floor-btn {
  background: var(--btn-bg);
  color: var(--text);
  border: 3px solid #4a5070;
  border-radius: 8px;
  padding: 16px 8px;
  font-size: 1.4rem;
  font-weight: bold;
  cursor: pointer;
  transition: background 0.15s, transform 0.1s, border-color 0.15s;
  box-shadow: 0 4px 0 #1a1c2c;
  font-family: 'Courier New', monospace;
}

.floor-btn:hover {
  background: var(--btn-hover);
  border-color: var(--accent);
}

.floor-btn:focus-visible {
  outline: 3px solid var(--accent);
  outline-offset: 2px;
}

.floor-btn:active,
.floor-btn.pressed {
  background: var(--btn-active);
  color: var(--btn-active-text);
  transform: translateY(4px);
  box-shadow: none;
}

.floor-btn.queued {
  background: var(--highlight);
  color: #fff;
  border-color: var(--accent);
}

.queue {
  text-align: center;
  font-size: 1rem;
  color: #9ca3af;
}

.queue .label {
  margin-right: 4px;
}

#queue-list {
  color: var(--accent);
  font-weight: bold;
}

[hidden] {
  display: none !important;
}

@media (max-width: 360px) {
  .elevator-card {
    padding: 16px;
  }
  .floor-btn {
    padding: 12px 4px;
    font-size: 1.2rem;
  }
  .value {
    font-size: 1.4rem;
  }
  .doors {
    height: 60px;
  }
}

const state = {
  currentFloor: 1,
  direction: 'idle',
  queue: [],
  moving: false,
  intervalId: null,
  doorTimeoutId: null
};

const floorDisplay = document.getElementById('current-floor');
const directionDisplay = document.getElementById('direction');
const queueList = document.getElementById('queue-list');
const doors = document.getElementById('doors');
const floorButtons = document.querySelectorAll('.floor-btn');

function updateDisplay() {
  floorDisplay.textContent = state.currentFloor;
  directionDisplay.textContent = state.direction === 'idle' ? 'Idle' : state.direction === 'up' ? 'Up' : 'Down';
  queueList.textContent = state.queue.length ? state.queue.join(', ') : 'empty';
  floorButtons.forEach(btn => {
    const floor = parseInt(btn.dataset.floor, 10);
    btn.classList.toggle('queued', state.queue.includes(floor));
  });
}

function openDoors() {
  doors.classList.add('open');
  if (state.doorTimeoutId) clearTimeout(state.doorTimeoutId);
  state.doorTimeoutId = setTimeout(() => {
    doors.classList.remove('open');
    state.doorTimeoutId = null;
  }, 1000);
}

function moveStep() {
  if (state.queue.length === 0) {
    state.direction = 'idle';
    state.moving = false;
    clearInterval(state.intervalId);
    state.intervalId = null;
    updateDisplay();
    return;
  }

  const target = state.queue[0];
  if (state.currentFloor === target) {
    state.queue.shift();
    openDoors();
    updateDisplay();
    if (state.queue.length === 0) {
      state.direction = 'idle';
      state.moving = false;
      clearInterval(state.intervalId);
      state.intervalId = null;
    }
    return;
  }

  if (state.currentFloor < target) {
    state.direction = 'up';
    state.currentFloor++;
  } else {
    state.direction = 'down';
    state.currentFloor--;
  }
  updateDisplay();

  if (state.currentFloor === target) {
    state.queue.shift();
    openDoors();
    updateDisplay();
    if (state.queue.length === 0) {
      state.direction = 'idle';
      state.moving = false;
      clearInterval(state.intervalId);
      state.intervalId = null;
    }
  }
}

function startMoving() {
  if (state.moving) return;
  state.moving = true;
  state.intervalId = setInterval(moveStep, 1000);
}

function enqueueFloor(floor) {
  if (floor === state.currentFloor && state.queue.length === 0) {
    openDoors();
    return;
  }
  if (!state.queue.includes(floor)) {
    state.queue.push(floor);
    updateDisplay();
    startMoving();
  }
}

floorButtons.forEach(btn => {
  btn.addEventListener('click', () => {
    const floor = parseInt(btn.dataset.floor, 10);
    enqueueFloor(floor);
  });
});

updateDisplay();
